# OrientCSG / 3D Slicer / mandibular surface-mesh section
# Generated by R. Paste the complete block into Slicer's Python Interactor.
# The model and landmark coordinates must refer to the same world geometry.
import slicer
import vtk
import numpy as np

MODEL_NAME = __MODEL_NAME__
SECTION_LABEL = __SECTION_LABEL__
CAMERA_DISTANCE = __CAMERA_DISTANCE__
BASE_PARALLEL_SCALE_MM = 42.5  # Same 85 mm base vertical FOV as CT.
CAMERA_POSITION_DISTANCE_MM = 300.0
PSEC = __PSEC__
NORMAL = __NORMAL__
X_SCREEN_REFERENCE = __X_SCREEN_REFERENCE__
Y_PREFERRED = __Y_PREFERRED__
ARP_ORIGIN = __ARP_ORIGIN__
ARP_NORMAL = __ARP_NORMAL__
LM1_LINE = __LM1_LINE__
ANTERIOR_REFERENCE = __ANTERIOR_REFERENCE__

CREATE_FILLED_SECTION = True
CREATE_SECTION_OUTLINE = False
CREATE_ARP_PLANE = True
CREATE_LM1_LINE_POINT = True
CREATE_ORTHOGONAL_VIEW = True
CREATE_SECTION_PLANE = True
REFERENCE_PLANE_SIZE_MM = 90.0
REFERENCE_PLANE_VISIBLE_BY_DEFAULT = False


def nrm(v):
    v = np.asarray(v, dtype=float)
    length = np.linalg.norm(v)
    if length < 1e-12:
        raise ValueError('Cannot normalize a near-zero vector.')
    return v / length


def dot3(a, b):
    return float(np.dot(a, b))


def make_camera_axes(normal, x_reference, y_preferred):
    # Identical handedness and sign resolution to the CT SliceToRAS routine.
    z_axis = nrm(normal)
    y_axis = np.asarray(y_preferred, dtype=float)
    y_axis = y_axis - dot3(y_axis, z_axis) * z_axis
    if np.linalg.norm(y_axis) < 1e-12:
        raise ValueError('Anatomical vertical is collinear with section normal.')
    y_axis = nrm(y_axis)
    x_axis = nrm(np.cross(y_axis, z_axis))
    x_ref = np.asarray(x_reference, dtype=float)
    x_ref = x_ref - dot3(x_ref, z_axis) * z_axis
    if np.linalg.norm(x_ref) > 1e-12 and dot3(x_axis, nrm(x_ref)) < 0:
        z_axis = -z_axis
        x_axis = nrm(np.cross(y_axis, z_axis))
    x_axis = nrm(np.cross(y_axis, z_axis))
    z_axis = nrm(np.cross(x_axis, y_axis))
    return x_axis, y_axis, z_axis


def get_target_model():
    candidates = [
        node for node in slicer.util.getNodesByClass('vtkMRMLModelNode')
        if node.GetName() == MODEL_NAME and node.GetPolyData() is not None
        and node.GetPolyData().GetNumberOfCells() > 0
    ]
    if len(candidates) != 1:
        available = [node.GetName() for node in slicer.util.getNodesByClass('vtkMRMLModelNode')]
        raise ValueError(
            f'Expected exactly one model named {MODEL_NAME!r}; found {len(candidates)}. '
            f'Available models: {available}'
        )
    return candidates[0]


def get_polydata_in_world(model_node):
    transform = vtk.vtkGeneralTransform()
    slicer.vtkMRMLTransformNode.GetTransformBetweenNodes(
        model_node.GetParentTransformNode(), None, transform
    )
    tf = vtk.vtkTransformPolyDataFilter()
    tf.SetInputData(model_node.GetPolyData())
    tf.SetTransform(transform)
    tf.Update()
    out = vtk.vtkPolyData()
    out.DeepCopy(tf.GetOutput())
    return out


def cut_mesh(polydata, point, normal):
    plane = vtk.vtkPlane()
    plane.SetOrigin(*[float(v) for v in point])
    plane.SetNormal(*[float(v) for v in normal])
    cutter = vtk.vtkCutter()
    cutter.SetCutFunction(plane)
    cutter.SetInputData(polydata)
    cutter.Update()
    cleaner = vtk.vtkCleanPolyData()
    cleaner.SetInputData(cutter.GetOutput())
    cleaner.Update()
    stripper = vtk.vtkStripper()
    stripper.SetInputData(cleaner.GetOutput())
    stripper.Update()
    outline = vtk.vtkPolyData()
    outline.DeepCopy(stripper.GetOutput())
    return outline


def filled_section(outline):
    triangulator = vtk.vtkContourTriangulator()
    triangulator.SetInputData(outline)
    triangulator.Update()
    filled = vtk.vtkPolyData()
    filled.DeepCopy(triangulator.GetOutput())
    return filled


def remove_previous_outputs():
    prefixes = ('OrientCSG_mandible_', 'OrientCSG_ARP',
                'OrientCSG_LM1_Line', 'OrientCSG_OrthogonalView_',
                'OrientCSG_SectionPlane_', 'OrientCSG_scale_')
    for cls in ('vtkMRMLModelNode', 'vtkMRMLMarkupsPlaneNode',
                'vtkMRMLMarkupsLineNode', 'vtkMRMLMarkupsFiducialNode'):
        for node in list(slicer.util.getNodesByClass(cls)):
            if node.GetName().startswith(prefixes) and node.GetName() != MODEL_NAME:
                slicer.mrmlScene.RemoveNode(node)


def add_polydata(polydata, name, color, opacity=1.0, line_width=3.0):
    node = slicer.mrmlScene.AddNewNodeByClass('vtkMRMLModelNode', name)
    node.SetAndObservePolyData(polydata)
    node.CreateDefaultDisplayNodes()
    display = node.GetDisplayNode()
    display.SetColor(*color)
    display.SetOpacity(opacity)
    display.SetLineWidth(line_width)
    display.SetBackfaceCulling(0)
    for method, value in (('SetLighting', False), ('SetAmbient', 1.0),
                          ('SetDiffuse', 0.0), ('SetSpecular', 0.0)):
        try:
            getattr(display, method)(value)
        except Exception:
            pass
    return node


def add_arp_plane():
    if not CREATE_ARP_PLANE:
        return None
    node = slicer.mrmlScene.AddNewNodeByClass('vtkMRMLMarkupsPlaneNode', 'OrientCSG_ARP')
    try:
        node.SetOriginWorld(*[float(v) for v in ARP_ORIGIN])
    except Exception:
        node.SetOriginWorld(ARP_ORIGIN)
    try:
        node.SetNormalWorld(*[float(v) for v in ARP_NORMAL])
    except Exception:
        node.SetNormalWorld(ARP_NORMAL)
    node.CreateDefaultDisplayNodes()
    node.SetLocked(True)
    try:
        node.SetSizeWorld([90.0, 90.0])
    except Exception:
        pass
    display = node.GetDisplayNode()
    display.SetColor(0.0, 1.0, 0.0)
    display.SetOpacity(0.45)
    display.SetVisibility(False)  # Avoid obscuring the section; enable for verification.
    return node


def add_reference_plane(name, origin, normal, color):
    # A hidden geometric guide; enable it in Slicer's Data module if needed.
    node = slicer.mrmlScene.AddNewNodeByClass('vtkMRMLMarkupsPlaneNode', name)
    try:
        node.SetOriginWorld(*[float(v) for v in origin])
    except Exception:
        node.SetOriginWorld(origin)
    try:
        node.SetNormalWorld(*[float(v) for v in normal])
    except Exception:
        node.SetNormalWorld(normal)
    node.CreateDefaultDisplayNodes()
    node.SetLocked(True)
    try:
        node.SetSizeWorld([REFERENCE_PLANE_SIZE_MM, REFERENCE_PLANE_SIZE_MM])
    except Exception:
        pass
    display = node.GetDisplayNode()
    display.SetColor(*color)
    display.SetOpacity(0.35)
    display.SetVisibility(REFERENCE_PLANE_VISIBLE_BY_DEFAULT)
    return node


def add_orientation_guides():
    # Avizo/Amira OrthogonalView has the in-plane X direction as its normal.
    orthogonal_node = None
    section_plane_node = None
    if CREATE_ORTHOGONAL_VIEW:
        orthogonal_node = add_reference_plane(
            f'OrientCSG_OrthogonalView_{SECTION_LABEL}', PSEC, X_AXIS,
            (0.2, 0.65, 1.0)
        )
    if CREATE_SECTION_PLANE:
        section_plane_node = add_reference_plane(
            f'OrientCSG_SectionPlane_{SECTION_LABEL}', PSEC, Z_AXIS,
            (1.0, 0.65, 0.15)
        )
    return orthogonal_node, section_plane_node


def add_lm1_line_point():
    if not CREATE_LM1_LINE_POINT:
        return None
    node = slicer.mrmlScene.AddNewNodeByClass(
        'vtkMRMLMarkupsFiducialNode', 'OrientCSG_LM1_Line'
    )
    node.CreateDefaultDisplayNodes()
    node.AddControlPointWorld(vtk.vtkVector3d(*[float(v) for v in LM1_LINE]))
    node.SetLocked(True)
    display = node.GetDisplayNode()
    display.SetSelectedColor(1.0, 0.0, 0.0)
    display.SetVisibility(False)
    return node


def configure_3d_view():
    widget = slicer.app.layoutManager().threeDWidget(0)
    if widget is None:
        raise ValueError('3D Slicer has no active 3D view.')
    view = widget.threeDView()
    view_node = view.mrmlViewNode()
    view_node.SetBackgroundColor(0.0, 0.0, 0.0)
    view_node.SetBackgroundColor2(0.0, 0.0, 0.0)
    view_node.SetBoxVisible(False)
    view_node.SetAxisLabelsVisible(False)
    view_node.SetOrientationMarkerType(0)
    view_node.SetRulerType(0)  # No 3D ruler for mandibular mesh sections.
    try:
        view_node.SetRenderMode(view_node.Orthographic)
    except Exception:
        pass
    return view


def set_camera(position, target, up):
    view = configure_3d_view()
    camera_node = view.cameraNode()
    camera = camera_node.GetCamera()
    camera.SetPosition(*[float(v) for v in position])
    camera.SetFocalPoint(*[float(v) for v in target])
    camera.SetViewUp(*[float(v) for v in up])
    camera.ParallelProjectionOn()
    camera.OrthogonalizeViewUp()
    camera.SetParallelScale(BASE_PARALLEL_SCALE_MM * CAMERA_DISTANCE)
    camera.SetClippingRange(1.0, 5000.0)
    camera_node.Modified()
    view.forceRender()
    return camera


def restore_view():
    # Restore section-facing camera (including its anatomical viewing side).
    set_camera(PSEC + CAMERA_POSITION_DISTANCE_MM * Z_AXIS, PSEC, Y_AXIS)
    if ARP_NODE is not None:
        ARP_NODE.GetDisplayNode().SetVisibility(False)
    if LM1_NODE is not None:
        LM1_NODE.GetDisplayNode().SetVisibility(False)
    for guide in (ORTHOGONAL_NODE, SECTION_PLANE_NODE):
        if guide is not None:
            guide.GetDisplayNode().SetVisibility(False)


def show_verification_view():
    # The ARP and the section plane are edge-on, as in CT verification.
    view_dir = nrm(np.cross(ARP_NORMAL, Z_AXIS))
    camera_offset = -view_dir
    # For CS3, the verification view must always be from anatomical anterior.
    # Switching the LM1 side must not switch this auxiliary camera to posterior.
    if SECTION_LABEL.upper() == 'CS3' and dot3(camera_offset, ANTERIOR_REFERENCE) < 0:
        camera_offset = -camera_offset
    set_camera(PSEC + CAMERA_POSITION_DISTANCE_MM * camera_offset, PSEC, ARP_NORMAL)
    if ARP_NODE is not None:
        ARP_NODE.GetDisplayNode().SetVisibility(True)
    if LM1_NODE is not None:
        LM1_NODE.GetDisplayNode().SetVisibility(True)


# Run. Geometry of the original model is never modified.
modelNode = get_target_model()
worldPolyData = get_polydata_in_world(modelNode)
X_AXIS, Y_AXIS, Z_AXIS = make_camera_axes(NORMAL, X_SCREEN_REFERENCE, Y_PREFERRED)
outline = cut_mesh(worldPolyData, PSEC, Z_AXIS)
if outline.GetNumberOfPoints() == 0:
    raise ValueError(f'{SECTION_LABEL}: section plane does not intersect model {MODEL_NAME!r}.')

remove_previous_outputs()
sectionNode = None
filled = filled_section(outline) if CREATE_FILLED_SECTION else None
if filled is not None and filled.GetNumberOfCells() > 0:
    sectionNode = add_polydata(
        filled, f'OrientCSG_mandible_{SECTION_LABEL}_filled', (1.0, 1.0, 1.0)
    )
else:
    print('WARNING: Could not fill section contours; showing outline only.')
if CREATE_SECTION_OUTLINE or sectionNode is None:
    outlineNode = add_polydata(
        outline, f'OrientCSG_mandible_{SECTION_LABEL}_outline', (1.0, 1.0, 1.0),
        line_width=4.0
    )
else:
    outlineNode = None

# Keep the input mesh but reduce its visual dominance.
modelNode.CreateDefaultDisplayNodes()
originalDisplay = modelNode.GetDisplayNode()
originalDisplay.SetVisibility(True)
originalDisplay.SetOpacity(0.20)
ARP_NODE = add_arp_plane()
LM1_NODE = add_lm1_line_point()
ORTHOGONAL_NODE, SECTION_PLANE_NODE = add_orientation_guides()
restore_view()

print(f'OrientCSG mandibular MESH / {SECTION_LABEL}: {MODEL_NAME}')
print('PSEC (RAS):', PSEC)
print('Section X (RAS):', X_AXIS)
print('Section Y / superior (RAS):', Y_AXIS)
print('Section Z / viewing normal (RAS):', Z_AXIS)
print('Commands: restore_view(), show_verification_view()')
print('Hidden reference planes: OrientCSG_OrthogonalView and OrientCSG_SectionPlane (toggle in Data).')
print('Source mesh coordinates were not modified.')
